import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes — 2020","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-2020.md","filePath":"aireblock-releases/AireForms/aireforms-2020.md","lastUpdated":1786969392000}`),a={name:`aireblock-releases/AireForms/aireforms-2020.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes-—-2020" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes — 2020</span> <a class="header-anchor" href="#aireforms-release-notes-—-2020" aria-label="Permalink to “AireForms Release Notes — 2020”">​</a></h1><p>This page contains the AireForms releases published during 2020.</p><h2 id="version-4-28-7-—-single-pass-form-context" tabindex="-1">Version 4.28.7 — Single Pass Form Context <a class="header-anchor" href="#version-4-28-7-—-single-pass-form-context" aria-label="Permalink to “Version 4.28.7 — Single Pass Form Context”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 21, 2020</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added organisation code and token, when present, to the form context for Single Pass forms</li></ul><h2 id="version-4-28-6-—-patient-forms-history-api-fix" tabindex="-1">Version 4.28.6 — Patient Forms History API Fix <a class="header-anchor" href="#version-4-28-6-—-patient-forms-history-api-fix" aria-label="Permalink to “Version 4.28.6 — Patient Forms History API Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 21, 2020</p></blockquote><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved a defect in the PatientForms History API</li></ul><h2 id="version-4-28-4-—-pdf-generation-improvements" tabindex="-1">Version 4.28.4 — PDF Generation Improvements <a class="header-anchor" href="#version-4-28-4-—-pdf-generation-improvements" aria-label="Permalink to “Version 4.28.4 — PDF Generation Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 15, 2020</p></blockquote><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Improved PDF generation support for malformed HTML and tag processing</li></ul><h2 id="version-4-28-3-—-date-addition-xpath-function" tabindex="-1">Version 4.28.3 — Date Addition XPath Function <a class="header-anchor" href="#version-4-28-3-—-date-addition-xpath-function" aria-label="Permalink to “Version 4.28.3 — Date Addition XPath Function”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 14, 2020</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a new <code>date-add</code> XPath function for date addition</li></ul><h2 id="version-4-28-2-—-form-metadata-performance" tabindex="-1">Version 4.28.2 — Form Metadata Performance <a class="header-anchor" href="#version-4-28-2-—-form-metadata-performance" aria-label="Permalink to “Version 4.28.2 — Form Metadata Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 3, 2020</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved performance when retrieving form metadata</li></ul><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an API issue where only one instance of form metadata was returned</li></ul><h2 id="version-4-28-1-—-pdf-generation-fix" tabindex="-1">Version 4.28.1 — PDF Generation Fix <a class="header-anchor" href="#version-4-28-1-—-pdf-generation-fix" aria-label="Permalink to “Version 4.28.1 — PDF Generation Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 1, 2020</p></blockquote><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved a PDF generation issue involving malformed tags</li></ul><h2 id="version-4-28-0-—-workflow-integration-pdf-highlighting" tabindex="-1">Version 4.28.0 — Workflow Integration &amp; PDF Highlighting <a class="header-anchor" href="#version-4-28-0-—-workflow-integration-pdf-highlighting" aria-label="Permalink to “Version 4.28.0 — Workflow Integration &amp; PDF Highlighting”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 25, 2020</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added pluggable workflow integration</li><li>Added the ability to highlight a Yes/No or Select control in generated PDFs based on the selected answer</li><li>Transiently send the organisation code as a query parameter on the AireGlu deliverer</li></ul><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved Image Select styling</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where <code>/patientforms/api/latest</code> did not return the expected number of forms</li><li>Resolved a spurious help icon location in repeat layouts</li></ul><h2 id="version-4-27-2-—-tokenisation-configuration-fix" tabindex="-1">Version 4.27.2 — Tokenisation Configuration Fix <a class="header-anchor" href="#version-4-27-2-—-tokenisation-configuration-fix" aria-label="Permalink to “Version 4.27.2 — Tokenisation Configuration Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 23, 2020</p></blockquote><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an error when calling a Single Pass form for an organisation with no organisation-level tokenisation service override</li></ul><h2 id="version-4-27-1-—-pdf-api-improvements" tabindex="-1">Version 4.27.1 — PDF &amp; API Improvements <a class="header-anchor" href="#version-4-27-1-—-pdf-api-improvements" aria-label="Permalink to “Version 4.27.1 — PDF &amp; API Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 16, 2020</p></blockquote><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where explanatory text was not shown in PDFs when hidden from the edit view</li></ul><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Changed an API query method from GET to POST to align with .NET Framework expectations around body content</li></ul><h2 id="version-4-27-0-—-form-metadata-extracts-submission-messages" tabindex="-1">Version 4.27.0 — Form Metadata, Extracts &amp; Submission Messages <a class="header-anchor" href="#version-4-27-0-—-form-metadata-extracts-submission-messages" aria-label="Permalink to “Version 4.27.0 — Form Metadata, Extracts &amp; Submission Messages”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 11, 2020</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for retrieving metadata for multiple form key/version combinations</li><li>Added support for storing customer-defined form metadata in a form definition</li><li>Added post-submission success messages, for example information returned from an integrated system</li><li>Added the <code>nf:multi-select-values</code> helper XPath function</li><li>Added support for extracting repeating data</li><li>Added support for <code>nillable</code> in the XSD schema generation API</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Form definition cloner can now show only forms not already present in the destination directory</li><li>Preview forms are filtered from the <code>allAvailableForms</code> API</li></ul><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed data debug page refresh</li><li>Fixed initial values on explanatory text not displaying on forms</li><li>Fixed help text not appearing on iOS 12</li><li>Fixed calculated explanatory text fields not displaying in PDF output</li></ul><h2 id="version-4-26-0-—-organisation-ids-extract-api-improvements" tabindex="-1">Version 4.26.0 — Organisation IDs &amp; Extract API Improvements <a class="header-anchor" href="#version-4-26-0-—-organisation-ids-extract-api-improvements" aria-label="Permalink to “Version 4.26.0 — Organisation IDs &amp; Extract API Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 10, 2020</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for storing an organisation ID as part of form instance data</li><li>Propagate Creator Organisation ID to plugins</li><li>Extended extract APIs to support extracting form data for any data type</li><li>Allow all forms to be fetched in the External API, including wizard-style and integrated forms</li><li>Added a versionless Single Pass forms route</li><li>Added Created By and Modified By metadata to PatientForms API responses</li><li>Added design-time control of image size and compression</li></ul><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Delete or expire data stored through tokenised review</li><li>Removed extraneous Designer features implemented in other ways</li><li>Updated to MobX 6</li><li>Added <code>axios-retry</code> for form submissions on unstable networks</li><li>Improved submission error messaging</li><li>Improved Master Child summary heading styling</li><li>Better handling of <code>ResizeObserver</code> console errors</li></ul><h2 id="version-4-25-3-—-chunk-loading-improvements" tabindex="-1">Version 4.25.3 — Chunk Loading Improvements <a class="header-anchor" href="#version-4-25-3-—-chunk-loading-improvements" aria-label="Permalink to “Version 4.25.3 — Chunk Loading Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 28, 2020</p></blockquote><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Handle chunk loading errors more gracefully</li><li>Stop logging <code>ResizeObserver loop limit exceeded</code> errors</li></ul><h2 id="version-4-25-2-—-single-pass-version-redirects" tabindex="-1">Version 4.25.2 — Single Pass Version Redirects <a class="header-anchor" href="#version-4-25-2-—-single-pass-version-redirects" aria-label="Permalink to “Version 4.25.2 — Single Pass Version Redirects”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 24, 2020</p></blockquote><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Stale URLs pointing to deprecated or withdrawn Single Pass forms now redirect to the latest production version when available</li></ul><h2 id="version-4-25-1-—-email-delivery-channel-fixes" tabindex="-1">Version 4.25.1 — Email &amp; Delivery Channel Fixes <a class="header-anchor" href="#version-4-25-1-—-email-delivery-channel-fixes" aria-label="Permalink to “Version 4.25.1 — Email &amp; Delivery Channel Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 22, 2020</p></blockquote><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added a &quot;do not reply to this email&quot; message to eConsultation submissions</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed delivery channel overrides duplicating organisation configuration</li></ul><h2 id="version-4-25-0-—-dynamic-treatment-plans-performance" tabindex="-1">Version 4.25.0 — Dynamic Treatment Plans &amp; Performance <a class="header-anchor" href="#version-4-25-0-—-dynamic-treatment-plans-performance" aria-label="Permalink to “Version 4.25.0 — Dynamic Treatment Plans &amp; Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 8, 2020</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for dynamic or patient-specific treatment plan workflows</li><li>Added a create route that does not require an instance ID</li><li>Added a display type to the Lazy Dropdown control</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved performance of the form data extract API</li><li>Moved database patching to a Flyway database container</li><li>Updated Fonto to address performance regressions</li><li>Refactored full-width buttons to be a display type rather than a separate control</li><li>Improved AA contrast compliance for highlighted sections</li><li>Improved XSD generation for image controls</li><li>Improved built-in date validation to respect local time and time zones</li><li>Improved reference data nodeset ordering consistency across browsers</li></ul><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved a Safari issue where controls did not appear in the correct column</li><li>Fixed Lazy Dropdowns not repopulating correctly on edited forms</li></ul><h3 id="🔧-maintenance" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Removed the legacy logo retriever</li></ul><h2 id="version-4-24-0-—-generic-data-lookup-form-context" tabindex="-1">Version 4.24.0 — Generic Data Lookup &amp; Form Context <a class="header-anchor" href="#version-4-24-0-—-generic-data-lookup-form-context" aria-label="Permalink to “Version 4.24.0 — Generic Data Lookup &amp; Form Context”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 27, 2020</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added environment-level minimum delivery status configuration</li><li>Added the ability to set form context values in a composite form via configuration</li><li>Added compact mode for Image Selector</li><li>Added Generic Data Lookup</li><li>Added debounce to Lazy Buttons</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved Character Counter styling</li><li>Improved GDS Section highlight styling consistency</li><li>Improved validation to prevent empty required fields in a repeat from being submitted</li></ul><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed Scribble control nib size</li><li>Resolved lazy-loading related screen jumping</li><li>Resolved missing end lines on boxes in Single Select and Multi Select controls</li></ul><h2 id="version-4-23-0-—-aireglu-delivery-channel" tabindex="-1">Version 4.23.0 — AireGlu Delivery Channel <a class="header-anchor" href="#version-4-23-0-—-aireglu-delivery-channel" aria-label="Permalink to “Version 4.23.0 — AireGlu Delivery Channel”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 5, 2020</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added AireGlu delivery channel</li><li>Added a new form status to better support testing paths to live, such as UAT</li><li>Allow explanatory text to be set through calculations</li><li>Added the <code>matches()</code> XPath function</li></ul><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved email address validation</li><li>Improved end-to-end diagnostic log tracing</li><li>Upgraded the Fonto library</li><li>Improved load performance</li><li>Improved in-control validation for Text Area fields</li></ul><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed a security policy defect affecting the Video control</li></ul><h2 id="version-4-22-0-—-accessibility-improvements" tabindex="-1">Version 4.22.0 — Accessibility Improvements <a class="header-anchor" href="#version-4-22-0-—-accessibility-improvements" aria-label="Permalink to “Version 4.22.0 — Accessibility Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 20, 2020</p></blockquote><h3 id="♿-accessibility" tabindex="-1">♿ Accessibility <a class="header-anchor" href="#♿-accessibility" aria-label="Permalink to “♿ Accessibility”">​</a></h3><ul><li>Added configurable accessibility and privacy notice footer links</li><li>Added a screen reader prompt when a form has loaded</li><li>Added screen reader prompts when changing pages in Wizard layouts</li><li>Improved Wizard layout tab order</li><li>Correctly linked Boolean Button labels for screen readers</li><li>Improved explanatory text hyperlink contrast in the GDS theme</li><li>Improved focus-state highlighting on navigation buttons in the GDS theme</li></ul><h3 id="🐞-bug-fixes-12" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-12" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed instance validation on field focus</li></ul><h2 id="version-4-21-0-—-internationalisation" tabindex="-1">Version 4.21.0 — Internationalisation <a class="header-anchor" href="#version-4-21-0-—-internationalisation" aria-label="Permalink to “Version 4.21.0 — Internationalisation”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 15, 2020</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for multiple languages for form names</li><li>Added general Wizard UI translations</li><li>Added translated PDF labels when a language resource exists</li><li>Added internationalisation support for Split Date controls</li><li>Added internationalisation support for Liquid templates in delivery channels</li><li>Added a favicon</li></ul><h3 id="⚡-improvements-11" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-11" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Form compiler now selects the correct resource based on language</li><li>Browser language is passed with form definition requests</li><li>Added translations for &quot;With other&quot; and &quot;Missing or incorrect value&quot;</li><li>Improved Barcode Scanner performance</li></ul><h3 id="🐞-bug-fixes-13" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-13" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an Internet Explorer issue where the Wizard footer was not always at the bottom of the page</li></ul><h2 id="version-4-20-0-—-pdf-links-form-launcher-improvements" tabindex="-1">Version 4.20.0 — PDF Links &amp; Form Launcher Improvements <a class="header-anchor" href="#version-4-20-0-—-pdf-links-form-launcher-improvements" aria-label="Permalink to “Version 4.20.0 — PDF Links &amp; Form Launcher Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 27, 2020</p></blockquote><h3 id="✨-new-features-9" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-9" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for external site links in PDFs</li><li>Added classification ordering to the form launcher</li><li>Added a &quot;Not applicable / No preference&quot; option for optional Slider inputs</li><li>Added the ability to configure a Call to Action form in the Organisation admin screen</li><li>Added Form Context API support for Wizard-style forms</li></ul><h3 id="⚡-improvements-12" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-12" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved mobile organisation logo and text behaviour</li></ul><h3 id="🐞-bug-fixes-14" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-14" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved logo and text bleed issues in PDFs</li><li>Fixed Wizard footer positioning</li><li>Fixed bold explanatory text not displaying as bold in Wizard view</li><li>Fixed controls remaining selectable while the close confirmation dialog was open</li></ul><h2 id="version-4-19-2-—-invalid-token-messaging" tabindex="-1">Version 4.19.2 — Invalid Token Messaging <a class="header-anchor" href="#version-4-19-2-—-invalid-token-messaging" aria-label="Permalink to “Version 4.19.2 — Invalid Token Messaging”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 15, 2020</p></blockquote><h3 id="⚡-improvements-13" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-13" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved the client-side message shown when a token is invalid, missing or has already been used</li></ul><h2 id="version-4-19-1-—-static-resource-performance" tabindex="-1">Version 4.19.1 — Static Resource Performance <a class="header-anchor" href="#version-4-19-1-—-static-resource-performance" aria-label="Permalink to “Version 4.19.1 — Static Resource Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 7, 2020</p></blockquote><h3 id="⚡-improvements-14" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-14" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added the potential to serve static resources through a CDN for optimised load times</li><li>Reduced logging for production deployments</li></ul><h2 id="version-4-19-0-—-recaptcha-user-management" tabindex="-1">Version 4.19.0 — reCAPTCHA &amp; User Management <a class="header-anchor" href="#version-4-19-0-—-recaptcha-user-management" aria-label="Permalink to “Version 4.19.0 — reCAPTCHA &amp; User Management”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 2, 2020</p></blockquote><h3 id="✨-new-features-10" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-10" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added reCAPTCHA capability</li><li>Added a new user-management admin UI</li><li>Organisation name is now displayed on the Organisation admin screen</li><li>Users can select previous steps from the Wizard step menu</li></ul><h3 id="🐞-bug-fixes-15" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-15" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed Rich Text controls not marking themselves as visited on blur</li></ul><h2 id="version-4-18-1-—-axios-status-handling" tabindex="-1">Version 4.18.1 — Axios Status Handling <a class="header-anchor" href="#version-4-18-1-—-axios-status-handling" aria-label="Permalink to “Version 4.18.1 — Axios Status Handling”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 20, 2020</p></blockquote><h3 id="🐞-bug-fixes-16" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-16" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where Axios <code>statusText</code> could sometimes be empty</li></ul><h2 id="version-4-18-0-—-form-definitions-runtime-improvements" tabindex="-1">Version 4.18.0 — Form Definitions &amp; Runtime Improvements <a class="header-anchor" href="#version-4-18-0-—-form-definitions-runtime-improvements" aria-label="Permalink to “Version 4.18.0 — Form Definitions &amp; Runtime Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 18, 2020</p></blockquote><h3 id="✨-new-features-11" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-11" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Extract Data and Reports APIs can accept a list of subject identifiers for filtering</li><li>Added form definition overrides</li><li>Migrated all form definitions to a common tree structure with metadata attributes</li><li>Added support for custom email subject lines in email delivery channels</li></ul><h3 id="⚡-improvements-15" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-15" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Sanitise itemset display names retrieved from integrated reference data services</li><li>Improved styling of the form launcher</li><li>Improved Rich Text Accordion styling</li><li>Improved Wizard form banner and navigation, particularly for large forms</li><li>Allow the subject banner to be hidden in edit mode</li><li>Up-versioned forms are now set to Development status</li></ul><h3 id="🐞-bug-fixes-17" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-17" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved hiding of Repeat and Master Child controls in edit view</li></ul><h2 id="version-4-17-0-—-xsd-generation-jwt-support" tabindex="-1">Version 4.17.0 — XSD Generation &amp; JWT Support <a class="header-anchor" href="#version-4-17-0-—-xsd-generation-jwt-support" aria-label="Permalink to “Version 4.17.0 — XSD Generation &amp; JWT Support”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 27, 2020</p></blockquote><h3 id="✨-new-features-12" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-12" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Plugins can now pass a dictionary of data into form context</li><li>Added an XSD Generation API that dynamically generates a schema of form data</li><li>Added JWT bearer support for the runtime</li></ul><h3 id="⚡-improvements-16" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-16" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Replaced ReactLoadable with React lazy loading for improved performance</li><li>Audit improvements</li><li>Updated to .NET Core SDK 3.1.2</li></ul><h3 id="🐞-bug-fixes-18" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-18" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed explanatory text highlighting in read view</li><li>Resolved an issue where misconfigured delivery channels did not raise an error notification</li></ul><h2 id="version-4-16-1-—-dynamic-attachment-names" tabindex="-1">Version 4.16.1 — Dynamic Attachment Names <a class="header-anchor" href="#version-4-16-1-—-dynamic-attachment-names" aria-label="Permalink to “Version 4.16.1 — Dynamic Attachment Names”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 11, 2020</p></blockquote><h3 id="✨-new-features-13" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-13" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added customisable and dynamic file attachment names</li></ul><h3 id="🐞-bug-fixes-19" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-19" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved an issue where uploaded images in Annotated Image controls could disappear when resizing the screen</li><li>Fixed static images in read view</li><li>Resolved bind errors for control child wildcard elements such as <code>$ControlName/*</code></li></ul><h3 id="⚡-improvements-17" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-17" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Merged performance improvements from the 4.14.x release line</li></ul><h2 id="version-4-14-4-—-repeat-performance" tabindex="-1">Version 4.14.4 — Repeat Performance <a class="header-anchor" href="#version-4-14-4-—-repeat-performance" aria-label="Permalink to “Version 4.14.4 — Repeat Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 10, 2020</p></blockquote><h3 id="⚡-improvements-18" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-18" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved Internet Explorer 11 performance when adding or deleting rows in repeats on large forms</li></ul><h2 id="version-4-14-2-—-performance-improvements" tabindex="-1">Version 4.14.2 — Performance Improvements <a class="header-anchor" href="#version-4-14-2-—-performance-improvements" aria-label="Permalink to “Version 4.14.2 — Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 6, 2020</p></blockquote><h3 id="⚡-improvements-19" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-19" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Resolved performance issues introduced with JSS</li><li>Sections with no controls, or where all controls are hidden, are no longer rendered</li></ul><h2 id="version-4-15-1-—-submission-redirect-fix" tabindex="-1">Version 4.15.1 — Submission Redirect Fix <a class="header-anchor" href="#version-4-15-1-—-submission-redirect-fix" aria-label="Permalink to “Version 4.15.1 — Submission Redirect Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 20, 2020</p></blockquote><h3 id="🐞-bug-fixes-20" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-20" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed a bug in post-submission redirects</li></ul><h2 id="version-4-15-0-—-delivery-channel-pdf-improvements" tabindex="-1">Version 4.15.0 — Delivery Channel &amp; PDF Improvements <a class="header-anchor" href="#version-4-15-0-—-delivery-channel-pdf-improvements" aria-label="Permalink to “Version 4.15.0 — Delivery Channel &amp; PDF Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 14, 2020</p></blockquote><h3 id="✨-new-features-14" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-14" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a more relevant watermark when generating a PDF for a deleted form instance</li><li>Added rule-based delivery channel settings using XPath</li><li>Added the ability to override the default delivery address on a per-form basis in the Organisation admin screen</li></ul><h3 id="⚡-improvements-20" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-20" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Refactored the SPA into separate packages</li><li>Improved error messages for non-operable forms</li><li>Improved the Manage Users screen</li></ul><h3 id="🐞-bug-fixes-21" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-21" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed Annotated Image controls in repeats</li></ul><h2 id="version-4-14-1-—-read-view-slider-fixes" tabindex="-1">Version 4.14.1 — Read View &amp; Slider Fixes <a class="header-anchor" href="#version-4-14-1-—-read-view-slider-fixes" aria-label="Permalink to “Version 4.14.1 — Read View &amp; Slider Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 2, 2020</p></blockquote><h3 id="🐞-bug-fixes-22" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-22" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed Slider controls showing the pin when no value was selected</li><li>Fixed H1, H2 and underline elements not displaying in Rich Text read view</li><li>Fixed read view not displaying the first tab of some forms</li></ul>`,188)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};